import{_ as e,o as t,c as a,X as o}from"./chunks/framework.7fab6bae.js";const _=JSON.parse('{"title":"개인정보 처리방침","description":"紫微研习社 iztro.com의 방문 통계, 쿠키, 광고, 외부 서비스 이용 및 개인정보 관련 문의 방법을 안내합니다.","frontmatter":{"title":"개인정보 처리방침","description":"紫微研习社 iztro.com의 방문 통계, 쿠키, 광고, 외부 서비스 이용 및 개인정보 관련 문의 방법을 안내합니다.","head":[["link",{"rel":"canonical","href":"https://iztro.com/ko_KR/privacy"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://iztro.com/privacy"}],["link",{"rel":"alternate","hreflang":"zh-TW","href":"https://iztro.com/zh_TW/privacy"}],["link",{"rel":"alternate","hreflang":"en-US","href":"https://iztro.com/en_US/privacy"}],["link",{"rel":"alternate","hreflang":"ko-KR","href":"https://iztro.com/ko_KR/privacy"}],["link",{"rel":"alternate","hreflang":"ja-JP","href":"https://iztro.com/ja_JP/privacy"}],["link",{"rel":"alternate","hreflang":"vi-VN","href":"https://iztro.com/vi_VN/privacy"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://iztro.com/privacy"}],["meta",{"name":"robots","content":"max-image-preview:large"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"紫微研习社"}],["meta",{"property":"og:title","content":"개인정보 처리방침 | 紫微研习社"}],["meta",{"property":"og:description","content":"紫微研习社 iztro.com의 방문 통계, 쿠키, 광고, 외부 서비스 이용 및 개인정보 관련 문의 방법을 안내합니다."}],["meta",{"property":"og:url","content":"https://iztro.com/ko_KR/privacy"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["meta",{"property":"og:locale:alternate","content":"zh_TW"}],["meta",{"property":"og:locale:alternate","content":"en_US"}],["meta",{"property":"og:locale:alternate","content":"ja_JP"}],["meta",{"property":"og:locale:alternate","content":"vi_VN"}],["meta",{"property":"og:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"property":"og:image:width","content":"850"}],["meta",{"property":"og:image:height","content":"850"}],["meta",{"property":"og:image:alt","content":"紫微研习社"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"개인정보 처리방침 | 紫微研习社"}],["meta",{"name":"twitter:description","content":"紫微研习社 iztro.com의 방문 통계, 쿠키, 광고, 외부 서비스 이용 및 개인정보 관련 문의 방법을 안내합니다."}],["meta",{"name":"twitter:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"name":"twitter:image:alt","content":"紫微研习社"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://iztro.com/ko_KR/privacy#webpage\\",\\"url\\":\\"https://iztro.com/ko_KR/privacy\\",\\"name\\":\\"개인정보 처리방침 | 紫微研习社\\",\\"description\\":\\"紫微研习社 iztro.com의 방문 통계, 쿠키, 광고, 외부 서비스 이용 및 개인정보 관련 문의 방법을 안내합니다.\\",\\"inLanguage\\":\\"ko-KR\\",\\"isPartOf\\":{\\"@id\\":\\"https://iztro.com/#website\\"},\\"breadcrumb\\":{\\"@id\\":\\"https://iztro.com/ko_KR/privacy#breadcrumb\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"@id\\":\\"https://iztro.com/ko_KR/privacy#breadcrumb\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"紫微研习社\\",\\"item\\":\\"https://iztro.com/ko_KR/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"개인정보 처리방침\\",\\"item\\":\\"https://iztro.com/ko_KR/privacy\\"}]}]}"]]},"headers":[],"relativePath":"ko_KR/privacy.md","filePath":"ko_KR/privacy.md"}'),r={name:"ko_KR/privacy.md"},i=o('<h1 id="隐私政策" tabindex="-1">개인정보 처리방침 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;개인정보 처리방침 {#隐私政策}&quot;">​</a></h1><p>최종 업데이트: 2026년 11월 9일</p><h2 id="适用范围与运营者" tabindex="-1">적용 범위와 운영자 <a class="header-anchor" href="#适用范围与运营者" aria-label="Permalink to &quot;적용 범위와 운영자 {#适用范围与运营者}&quot;">​</a></h2><p>紫微研习社(<a href="https://iztro.com" target="_blank" rel="noreferrer">https://iztro.com</a>, 이하 ‘본 사이트’)는 SylarLong이 관리하며 iztro 개발 문서와 학습 자료를 제공합니다. 이 방침은 본 사이트의 문서 페이지에 적용됩니다. 개인정보 관련 문의는 <a href="mailto:sylarlong@gmail.com" target="_blank" rel="noreferrer">sylarlong@gmail.com</a>으로 보내 주세요.</p><p>링크로 연결된 명반 작성, 해석, AI 플랫폼, 코드 호스팅 및 결제 서비스는 각 제공자가 데이터를 처리합니다. 본 사이트에서 링크를 제공한다는 이유로 해당 서비스에 이 방침이 적용되지는 않습니다.</p><h2 id="浏览与访问统计" tabindex="-1">열람 및 방문 통계 <a class="header-anchor" href="#浏览与访问统计" aria-label="Permalink to &quot;열람 및 방문 통계 {#浏览与访问统计}&quot;">​</a></h2><p>문서를 읽기 위해 계정을 만들거나 이름, 생년월일, 출생 시각을 제출할 필요가 없습니다. 문서의 명반 작성 코드와 출생 정보는 학습용 예시입니다. 자신의 애플리케이션에서 iztro를 실행할 때의 데이터 처리 방식은 해당 애플리케이션의 구현에 따라 달라집니다.</p><p>본 사이트는 Google Analytics와 바이두 통계를 이용하여 방문 수, 페이지 이용 현황, 기기 분포를 파악하고 콘텐츠와 읽기 환경을 개선합니다. 해당 서비스는 방문 페이지, 방문 시각, 유입 페이지, 브라우저 및 기기 정보, IP 주소로 추정한 대략적인 지역, 쿠키 또는 유사 식별자를 처리할 수 있습니다. 호스팅 및 네트워크 제공자도 페이지 전송, 보안 유지, 장애 조사를 위해 IP 주소와 접속 기록을 처리할 수 있습니다.</p><p>자세한 내용은 <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google 개인정보처리방침</a>, <a href="https://policies.google.com/technologies/partner-sites" target="_blank" rel="noreferrer">파트너 사이트 또는 앱의 데이터를 Google이 사용하는 방식</a>, <a href="https://www.baidu.com/duty/yinsiquan.html" target="_blank" rel="noreferrer">바이두 개인정보 처리방침</a>을 확인해 주세요.</p><h2 id="Cookie与本地存储" tabindex="-1">쿠키와 로컬 저장소 <a class="header-anchor" href="#Cookie与本地存储" aria-label="Permalink to &quot;쿠키와 로컬 저장소 {#Cookie与本地存储}&quot;">​</a></h2><p>본 사이트와 사용하는 외부 서비스는 화면 설정 저장, 방문 통계, 광고 기능을 위해 쿠키 또는 유사 기술을 사용할 수 있습니다. 브라우저 설정에서 쿠키와 사이트 저장 데이터를 확인, 삭제, 차단할 수 있습니다. 삭제하면 화면 설정이 초기화되거나 일부 외부 기능에 영향이 있을 수 있습니다.</p><p><a href="https://tools.google.com/dlpage/gaoptout" target="_blank" rel="noreferrer">Google Analytics 차단 브라우저 부가 기능</a>을 이용하여 해당 서비스의 브라우저 측 측정을 제한할 수도 있습니다. 이 부가 기능은 바이두 통계나 다른 서비스를 제어하지 않습니다.</p><h2 id="GoogleAdSense与广告" tabindex="-1">Google AdSense와 광고 <a class="header-anchor" href="#GoogleAdSense与广告" aria-label="Permalink to &quot;Google AdSense와 광고 {#GoogleAdSense与广告}&quot;">​</a></h2><p>본 사이트는 Google AdSense를 사용할 예정입니다. 이 절은 관련 광고를 활성화한 이후의 데이터 처리를 설명하며, 현재 모든 페이지에 광고가 표시된다는 뜻은 아닙니다.</p><p>활성화 후 Google을 포함한 제3자 공급업체는 본 사이트나 다른 사이트의 과거 방문을 바탕으로 광고를 제공하기 위해 쿠키를 사용할 수 있습니다. Google의 광고 쿠키를 통해 Google과 파트너는 본 사이트 및 인터넷의 다른 사이트 방문에 기반한 개인 맞춤 광고를 제공할 수 있습니다. 참여하는 다른 광고 공급업체나 광고 네트워크도 쿠키 또는 유사 기술을 사용할 수 있습니다.</p><p><a href="https://www.google.com/settings/ads" target="_blank" rel="noreferrer">Google 광고 설정</a>에서 개인 맞춤 광고를 관리하거나, <a href="https://www.aboutads.info/choices/" target="_blank" rel="noreferrer">AboutAds 선택 도구</a>에서 일부 제3자 공급업체의 개인 맞춤 광고 쿠키를 관리할 수 있습니다. 광고 파트너에 대해서는 <a href="https://support.google.com/adsense/answer/9012903" target="_blank" rel="noreferrer">Google 광고 기술 제공업체 안내</a>를 확인해 주세요. 개인 맞춤 광고를 끄더라도 광고 자체가 없어지지는 않습니다.</p><p>페이지에 동의 관리 또는 개인정보 설정 메뉴가 제공되는 경우, 이를 통해 선택을 변경하거나 철회할 수 있습니다. 사전 동의가 필요한 처리는 해당 동의를 받은 후에 활성화해야 합니다. EEA, 영국, 스위스 이용자에게 개인 맞춤 광고를 제공할 때는 Google 인증 동의 관리 플랫폼이 필요합니다. 이 방침 자체가 동의 관리를 대신하지는 않습니다.</p><h2 id="外部资源与第三方服务" tabindex="-1">외부 리소스 및 제3자 서비스 <a class="header-anchor" href="#外部资源与第三方服务" aria-label="Permalink to &quot;외부 리소스 및 제3자 서비스 {#外部资源与第三方服务}&quot;">​</a></h2><p>일부 페이지는 GitHub, Shields.io, Skill Icons 등에서 이미지나 배지를 불러옵니다. 브라우저가 리소스를 요청할 때 제공자는 IP 주소, 브라우저 정보, 브라우저 정책에 따라 전송되는 유입 경로 정보를 받을 수 있습니다. 외부 링크를 열거나 PayPal 등 프로젝트 후원 수단을 사용할 때는 해당 서비스의 개인정보 처리방침을 확인해 주세요.</p><p>명반 작성, 해석 또는 AI 서비스에 출생 정보, 대화나 기타 자료를 제출하기 전에 해당 서비스의 개인정보 안내를 확인해 주세요. 본 사이트의 문서 페이지가 링크를 제공한다는 이유만으로 해당 서비스의 계정이나 대화 내용을 자동으로 받지는 않습니다.</p><h2 id="主动联系保存与披露" tabindex="-1">직접 문의, 보관 및 공개 <a class="header-anchor" href="#主动联系保存与披露" aria-label="Permalink to &quot;직접 문의, 보관 및 공개 {#主动联系保存与披露}&quot;">​</a></h2><p>이메일, WeChat 또는 GitHub로 작성자에게 연락하면 해당 서비스는 직접 제공한 계정, 연락처 및 메시지를 처리합니다. 작성자는 답변, 문제 조사, 요청 후속 처리를 위해 이 정보를 사용합니다. 문제와 관계없는 신분증, 비밀번호 또는 타인의 민감한 정보는 보내지 마세요. 공개 GitHub 토론은 다른 사람이 볼 수 있습니다.</p><p>문의 기록은 답변과 후속 연락에 필요한 기간 동안 보관합니다. 통계, 로그 및 광고 데이터의 보관 기간은 각 서비스의 설정과 정책에 따릅니다. 제공자는 다른 국가나 지역에서 데이터를 처리할 수 있습니다. 적용 법률, 보안 사고 또는 적법한 요청에 대응하기 위해 필요한 경우 정보가 공개될 수도 있습니다.</p><h2 id="你的选择与隐私请求" tabindex="-1">선택권과 개인정보 요청 <a class="header-anchor" href="#你的选择与隐私请求" aria-label="Permalink to &quot;선택권과 개인정보 요청 {#你的选择与隐私请求}&quot;">​</a></h2><p>브라우저 및 광고 설정 외에도 <a href="mailto:sylarlong@gmail.com" target="_blank" rel="noreferrer">sylarlong@gmail.com</a>으로 본 사이트의 데이터 처리에 관해 문의하거나 적용 법률에 따라 열람, 정정, 삭제 또는 동의 철회를 요청할 수 있습니다. 대상 서비스와 요청 내용을 알려 주세요. 요청과 본인의 관계를 확인해야 할 수 있습니다. 제3자가 독립적으로 보유하는 데이터는 해당 제공자에게 직접 요청해야 할 수 있습니다.</p><h2 id="政策更新" tabindex="-1">방침 변경 <a class="header-anchor" href="#政策更新" aria-label="Permalink to &quot;방침 변경 {#政策更新}&quot;">​</a></h2><p>통계, 광고 또는 기타 서비스가 변경되면 이 방침과 위의 날짜를 함께 갱신합니다. 다시 동의를 받아야 하는 변경은 해당 절차를 통해 동의를 요청해야 합니다.</p>',27),n=[i];function l(p,c,h,s,m,g){return t(),a("div",null,n)}const f=e(r,[["render",l]]);export{_ as __pageData,f as default};
